519	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
520	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
521	fn longs_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
522	    debug!("longs: name={}", p.get_name());
523	
524	    p.get_arguments()
525	        .filter_map(|a| {
526	            a.get_long_and_visible_aliases().map(|longs| {
527	                longs
528	                    .into_iter()
529	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
530	            })
531	        })
532	        .flatten()
533	        .collect()
534	}
535	
536	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
537	fn hidden_longs_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
538	    debug!("longs: name={}", p.get_name());
539	
540	    p.get_arguments()
541	        .filter_map(|a| {
542	            a.get_aliases().map(|longs| {
543	                longs.into_iter().map(|s| {
544	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
545	                })
546	            })
547	        })
548	        .flatten()
549	        .collect()
550	}
