598	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
599	///
600	/// Subcommand `rustup toolchain install` would be converted to
601	/// `("install", "rustup toolchain install")`.
602	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
603	    debug!("subcommands: name={}", p.get_name());
604	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
605	    p.get_subcommands()
606	        .flat_map(|sc| {
607	            sc.get_name_and_visible_aliases()
608	                .into_iter()
609	                .map(|s| populate_command_candidate(s, p, sc))
610	                .chain(
611	                    sc.get_aliases()
612	                        .map(|s| populate_command_candidate(s, p, sc).hide(true)),
613	                )
614	        })
615	        .collect()
616	}
617	
618	fn populate_command_candidate(
619	    candidate_name: &str,
620	    cmd: &clap::Command,
621	    subcommand: &clap::Command,
622	) -> CompletionCandidate {
623	    CompletionCandidate::new(candidate_name.to_owned())
624	        .help(subcommand.get_about().cloned())
625	        .id(Some(format!("command::{candidate_name}")))
626	        .tag(Some(
627	            cmd.get_subcommand_help_heading()
628	                .unwrap_or("Commands")
629	                .to_owned()
630	                .into(),
631	        ))
632	        .display_order(Some(subcommand.get_display_order()))
633	        .hide(subcommand.is_hide_set())
634	}
635	
636	/// Parse the short flags and find the first `takes_values` option.
637	///
638	/// Returns the raw leading flags, every matched argument, the first
639	/// `takes_values` option (if any), and the remaining unparsed flags.
640	fn parse_shortflags<'c, 's>(
641	    cmd: &'c clap::Command,
642	    mut short: clap_lex::ShortFlags<'s>,
643	) -> (
644	    String,
645	    Vec<&'c clap::Arg>,
646	    Option<&'c clap::Arg>,
647	    clap_lex::ShortFlags<'s>,
648	) {
649	    let takes_value_opt;
650	    let mut matched_opts = Vec::new();
651	    let mut leading_flags = String::new();
652	    // Find the first takes_values option.
653	    loop {
654	        match short.next_flag() {
655	            Some(Ok(opt)) => {
656	                leading_flags.push(opt);
657	                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
658	                if let Some(opt) = opt {
659	                    matched_opts.push(opt);
660	                }
661	                if opt
662	                    .map(|o| o.get_num_args().expect("built").takes_values())
663	                    .unwrap_or(false)
664	                {
665	                    takes_value_opt = opt;
666	                    break;
667	                }
668	            }
669	            Some(Err(_)) | None => {
670	                takes_value_opt = None;
671	                break;
672	            }
673	        }
674	    }
675	
676	    (leading_flags, matched_opts, takes_value_opt, short)
677	}
678	
679	/// Whether the argument can be addressed by the long flag `flag`,
680	/// including visible and hidden aliases.
681	fn is_long_match(arg: &clap::Arg, flag: &str) -> bool {
682	    arg.get_long() == Some(flag)
683	        || arg
684	            .get_all_aliases()
685	            .is_some_and(|aliases| aliases.contains(&flag))
686	}
687	
688	/// Whether the argument can be addressed by the short flag `flag`,
689	/// including visible and hidden aliases.
690	fn is_short_match(arg: &clap::Arg, flag: char) -> bool {
691	    arg.get_short() == Some(flag)
692	        || arg
693	            .get_all_short_aliases()
694	            .is_some_and(|aliases| aliases.contains(&flag))
695	}
696	
697	/// Remove candidates for arguments that conflict with arguments already
698	/// present on the command line.
699	///
700	/// Conflicts only need to be declared on one of the two arguments; a
701	/// candidate is removed when either it or an already-used argument names
702	/// the other as a conflict. Anything that is not an argument candidate
703	/// (positional values, subcommands, custom candidates) is left untouched.
704	fn filter_conflicting_candidates(
705	    completions: &mut Vec<CompletionCandidate>,
706	    cmd: &clap::Command,
707	    used_args: &[clap::Id],
708	) {
709	    if used_args.is_empty() {
710	        return;
711	    }
712	    completions.retain(|candidate| {
713	        let Some(arg) = candidate
714	            .get_id()
715	            .and_then(|id| id.strip_prefix("arg::"))
716	            .and_then(|id| cmd.get_arguments().find(|a| a.get_id() == id))
717	        else {
718	            return true;
719	        };
720	        !used_args.iter().any(|used_id| {
721	            cmd.get_arguments()
722	                .find(|a| a.get_id() == used_id)
723	                .is_some_and(|used| args_conflict(cmd, arg, used))
724	        })
725	    });
726	}
727	
728	/// Whether `first` and `second` conflict, no matter which one declares it.
729	fn args_conflict(cmd: &clap::Command, first: &clap::Arg, second: &clap::Arg) -> bool {
730	    cmd.get_arg_conflicts_with(first)
731	        .iter()
732	        .any(|c| c.get_id() == second.get_id())
733	        || cmd
734	            .get_arg_conflicts_with(second)
735	            .iter()
736	            .any(|c| c.get_id() == first.get_id())
737	}
738	
739	/// Parse the positional arguments. Return the new state and the new positional index.
740	fn parse_positional<'a>(
741	    cmd: &clap::Command,
742	    pos_index: usize,
743	    is_escaped: bool,
744	    state: ParseState<'a>,
745	) -> (ParseState<'a>, usize) {
746	    let pos_arg = cmd
747	        .get_positionals()
748	        .find(|p| p.get_index() == Some(pos_index));
749	    let num_args = pos_arg
750	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
751	        .unwrap_or(1);
752	
753	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
754	        if num_args > 1 {
755	            (ParseState::Pos((pos_index, 1)), pos_index)
756	        } else {
757	            if is_escaped {
758	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
759	            } else {
760	                (ParseState::ValueDone, pos_index + 1)
761	            }
762	        }
763	    };
764	    match state {
765	        ParseState::ValueDone => {
766	            update_state_with_new_positional(pos_index)
767	        },
768	        ParseState::Pos((prev_pos_index, num_arg)) => {
769	            if prev_pos_index == pos_index {
770	                if num_arg + 1 < num_args {
771	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
772	                } else {
773	                    if is_escaped {
774	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
775	                    } else {
776	                        (ParseState::ValueDone, pos_index + 1)
777	                    }
778	                }
779	            } else {
780	                update_state_with_new_positional(pos_index)
781	            }
782	        }
783	        ParseState::Opt(..) => unreachable!(
784	            "This branch won't be hit,
785	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
786	        ),
787	    }
788	}
789	
790	/// Parse optional flag argument. Return new state
791	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
792	    let range = opt.get_num_args().expect("built");
793	    let max = range.max_values();
794	    if count < max {
795	        ParseState::Opt((opt, count + 1))
796	    } else {
797	        ParseState::ValueDone
798	    }
799	}
800	
801	/// How many of an option's values an attached `=value` (or `-ovalue`) accounts
802	/// for, honoring the value delimiter.
803	fn attached_value_count(opt: &clap::Arg, value: &OsStr) -> usize {
804	    match (opt.get_value_delimiter(), value.to_str()) {
805	        (Some(delimiter), Some(value)) => value.split(delimiter).count(),
806	        _ => 1,
807	    }
808	}
809	
810	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
811	    cmd.get_positionals()
812	        .find(|a| a.get_index() == Some(pos_index))
813	        .map(|p| p.is_allow_hyphen_values_set())
814	        .unwrap_or(false)
815	}
816	
817	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
818	    let val = arg.to_value_os();
819	    if val.starts_with("-") {
820	        if let ParseState::Opt((opt, _)) = state {
821	            return opt.is_allow_hyphen_values_set();
822	        }
823	    }
824	
825	    false
826	}
827	
828	/// Whether a word can terminate a still-open multi-value option and start a
829	/// new argument instead, the way the parser would read it.
830	///
831	/// While an option still owes values, the parser greedily consumes every plain
832	/// word as one of its values; only flag-like words can switch to another
833	/// argument. An option that accepts hyphen values consumes those too.
834	fn can_switch_to_other_arg(pending: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
835	    if arg.is_escape() {
836	        // `--` cancels every pending option unless its values may start with `--`.
837	        return !pending.is_allow_hyphen_values_set();
838	    }
839	    if !arg.to_value_os().starts_with("-") {
840	        // A plain word is always another value of the pending option.
841	        return false;
842	    }
843	    if pending.is_allow_hyphen_values_set() {
844	        return false;
845	    }
846	    // `-` is a stdio/value, not a flag.
847	    if arg.is_stdio() {
848	        return false;
849	    }
850	    // Both long and short flag styles can start a new argument; unknown flags
851	    // still switch (and error during parsing) rather than become option values.
852	    arg.to_long().is_some() || arg.to_short().is_some()
853	}
