#![cfg(feature = "unstable-dynamic")]

use clap::{ArgGroup, Command};

fn tool_cmd() -> Command {
    Command::new("tool")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .disable_help_subcommand(true)
        .arg(
            clap::Arg::new("json")
                .long("json")
                .visible_alias("js")
                .action(clap::ArgAction::SetTrue),
        )
        .arg(
            clap::Arg::new("yaml")
                .long("yaml")
                .visible_alias("yml")
                .action(clap::ArgAction::SetTrue),
        )
        .group(
            ArgGroup::new("format")
                .args(["json", "yaml"])
                .required(true),
        )
        .arg(
            clap::Arg::new("output")
                .long("output")
                .value_parser(["file", "stream"]),
        )
        .subcommand(Command::new("run").disable_help_flag(true).disable_version_flag(true))
}

fn values(cmd: &mut Command, args: &[&str]) -> Vec<String> {
    let args: Vec<std::ffi::OsString> = args.iter().map(std::ffi::OsString::from).collect();
    let arg_index = args.len() - 1;
    clap_complete::engine::complete(cmd, args, arg_index, None)
        .unwrap()
        .into_iter()
        .map(|c| c.get_value().to_string_lossy().into_owned())
        .collect()
}

#[test]
fn scratch_group_behavior() {
    let mut cmd = tool_cmd();
    println!("empty:    {:?}", values(&mut cmd, &["tool", ""]));
    println!("--json :  {:?}", values(&mut cmd, &["tool", "--json", ""]));
    println!("--js   :  {:?}", values(&mut cmd, &["tool", "--js", ""]));
    println!("--yaml :  {:?}", values(&mut cmd, &["tool", "--yaml", ""]));
    println!("--yml  :  {:?}", values(&mut cmd, &["tool", "--yml", ""]));
    println!("json x2:  {:?}", values(&mut cmd, &["tool", "--json", "--json", ""]));
    println!("--output:  {:?}", values(&mut cmd, &["tool", "--output", ""]));
    println!("output f:  {:?}", values(&mut cmd, &["tool", "--output", "f"]));
    println!("output=,s: {:?}", values(&mut cmd, &["tool", "--output=", "s"]));
    println!("=pipe:   {:?}", values(&mut cmd, &["tool", "--output=pipe", ""]));
    println!("run:     {:?}", values(&mut cmd, &["tool", "run", ""]));
}

