    assert!(group_values(&["tool", "--bogus"]).is_empty());
    assert!(group_values(&["tool", "run", "--bogus"]).is_empty());
    assert!(group_values(&["tool", "run", "--t", ""]).is_empty() == false);
    assert_eq!(group_values(&["tool", "run", "--t"]), ["--text"]);
}

